import json


def for_model(response):
    """Return the string a host hands the model for one tools/call response."""
    if "error" in response:
        error = response["error"]
        return f"PROTOCOL ERROR {error['code']}: {error['message']}"
    result = response["result"]
    text = "\n".join(b["text"] for b in result.get("content", []) if b.get("type") == "text")
    if result.get("isError", False):
        return f"TOOL FAILED: {text}"
    if text:
        return text
    if "structuredContent" in result:
        return json.dumps(result["structuredContent"])
    return "(no content)"
